{
  "a_sentences": [
    {
      "a_text": "Selon la jurisprudence, une modification de l'incapacité de travail ou une nouvelle classification diagnostique ne suffisent pas à elles seules pour admettre une modification de l'état de fait ouvrant le droit à une révision; seule une modification substantielle des constatations médicales est déterminante.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Lorsqu'un motif de révision est avéré, le droit à la rente doit être examiné de manière complète, sans être lié aux évaluations antérieures.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Si l'autorité précédente s'écarte à tort d'une expertise médicale fiable, il existe un motif valable justifiant de s'en distancer.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Le Tribunal fédéral retient que, au vu des constatations des deux experts psychiatres en 2019 et 2024, on ne peut pas admettre une situation inchangée.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Le Tribunal fédéral renvoie la cause à la juridiction cantonale pour instruction complémentaire et nouvelle décision.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "La juridiction cantonale devra d'abord examiner si l'évaluation de la capacité de travail dans la consilium des experts BEGAZ est cohérente en soi et au regard des expertises partielles.",
      "b_propositions": ["P6"]
    }
  ]
}
